plans.query:
select (((select count(*)::int from "missions" where ("missions"."status" = $1 and "missions"."kind" <> $2 and not EXISTS (
  SELECT 1 FROM "clan_war_missions" WHERE "clan_war_missions"."mission_id" = "missions"."id"
) and "missions"."kind" <> $3 and ((("missions"."kind" <> $4 and "missions"."parent_mission_id" is null) and "missions"."origin_planet_id" = $5) or (("missions"."kind" = $6 or "missions"."parent_mission_id" is not null) and "missions"."target_planet_id" = $7))))) + ((select count(*)::int from "mining_runs" where ("mining_runs"."planet_id" = $8 and "mining_runs"."status" in ($9, $10)))) + ((select count(*)::int from "pirate_raids" where ("pirate_raids"."planet_id" = $11 and "pirate_raids"."status" in ($12, $13)))) + ((select count(*)::int from "trade_runs" where ("trade_runs"."planet_id" = $14 and "trade_runs"."status" in ($15, $16)))) + ((select count(*)::int from "intergalactic_convoy_runs" where ("intergalactic_convoy_runs"."planet_id" = $17 and "intergalactic_convoy_runs"."status" in ($18, $19)))) + ((select count(*)::int from "clan_war_contributions" where ("clan_war_contributions"."origin_planet_id" = $20 and "clan_war_contributions"."source_kind" = $21 and "clan_war_contributions"."status" not in ($22, $23, $24)))) + ((select count(*)::int from "clan_support_waves" where ("clan_support_waves"."origin_planet_id" = $25 and "clan_support_waves"."status" not in ($26, $27)))) + ((select count(distinct coalesce("root_wave_id", "id"))::int from "monument_waves" where ("monument_waves"."origin_planet_id" = $28 and "monument_waves"."status" not in ($29, $30)))) + ((select count(*)::int from "radiation_bomb_flights" where ("radiation_bomb_flights"."origin_planet_id" = $31 and "radiation_bomb_flights"."status" = $32))) + ((select count(*)::int from "unknown_signals" inner join "planets" on "planets"."id" = $33 where ("planets"."player_id" = "unknown_signals"."player_id" and "unknown_signals"."status" in ($34, $35, $36) and ("unknown_signals"."origin_planet_id" = $37 or ("planets"."kind" = $38 and not exists (select 1 from planets p where p.id = "unknown_signals"."origin_planet_id" and p.player_id = "unknown_signals"."player_id")))))))::int as used
